/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, AppliedUndef, E, Float, I, LambertW, Mul, Pow, Rational, Relational, Sym, components, derivative, expand, fn, heurisch, heurischWrapper, integrate, mul, pi, piecewise, pow, ratsimp, simplify, symbols } from '../../src';
import { sympyMatches, sympyStr } from '../sympy-str';
import { equivalent } from '../sympy-equivalent';

describe("doctests of sympy.integrals.heurisch", () => {
  it("components(sin(x)*cos(x)**2, x)", () => {
    const x = new Sym('x');
    expect(sympyMatches(components(mul(pow(fn('cos', [x], { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n })), fn('sin', [x], { evaluate: false })), x), '{x, cos(x), sin(x)}')).toBe(true);
  });
  it("heurisch(y*tan(x), x)", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(heurisch(mul(y, fn('tan', [x], { evaluate: false })), x))).toBe('y*log(tan(x)**2 + 1)/2');
  });
  it("heurisch(cos(n*x), x)", () => {
    const [n, x] = symbols('n x');
    expect(sympyStr(heurisch(fn('cos', [mul(n, x)], { evaluate: false }), x))).toBe('sin(n*x)/n');
  });
  it("heurisch_wrapper(cos(n*x), x)", () => {
    const [n, x] = symbols('n x');
    expect(sympyStr(heurischWrapper(fn('cos', [mul(n, x)], { evaluate: false }), x))).toBe('Piecewise((sin(n*x)/n, Ne(n, 0)), (x, True))');
  });
});

